@* Displays the step progress bar with clickable completed steps *@

<nav aria-label="Application progress" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative px-0">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item text-center flex-fill @status" role="listitem">
                @if (status == "completed")
                {
                    <button type="button"
                            class="btn btn-link p-0 text-decoration-none"
                            @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <span class="step-label d-block mt-1 text-success fw-semibold">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(status == "active" ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">
                            @(stepIndex + 1)
                        </span>
                        <span class="step-label d-block mt-1 @(status == "active" ? "fw-semibold text-primary" : "text-muted")">
                            @StepNames[stepIndex]
                        </span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "future";
    }
}

